<template><div class="page"><header><div><h2>你好，{{ userName }}</h2><p>{{ today }}</p></div></header><section class="stats"><button @click="$emit('navigate',{key:'my-course',name:'我的课程'})"><span>负责课程</span><strong>{{ courses.length }}</strong></button><button @click="$emit('navigate',{key:'my-task',name:'实验任务'})"><span>已发布任务</span><strong>{{ published }}</strong></button><button @click="$emit('navigate',{key:'my-task',name:'实验任务'})"><span>待发布草稿</span><strong>{{ drafts }}</strong></button><button @click="$emit('navigate',{key:'my-course',name:'我的课程'})"><span>学生人次</span><strong>{{ students }}</strong></button></section><section class="quick"><button v-for="a in actions" :key="a.key" @click="$emit('navigate',{key:a.key,name:a.name})"><svg viewBox="0 0 24 24"><path :d="a.icon"/></svg><span>{{ a.name }}</span></button></section><section class="card"><header><h3>最近教学任务</h3><button @click="$emit('navigate',{key:'my-task',name:'实验任务'})">查看全部</button></header><div v-for="t in tasks.slice(0,6)" :key="t.taskId" class="row"><div><strong>{{ t.taskTitle }}</strong><small>{{ t.courseName }} · {{ t.taskNo }}</small></div><span>{{ taskStatusLabel(t.taskStatus) }}</span><time>{{ t.deadline.replace('T',' ').slice(0,16) }}</time></div><div v-if="tasks.length===0" class="empty">暂无教学任务</div></section><p v-if="message" class="error">{{ message }}</p></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{userName}from'../../stores/authStore';import{getCoursePage,getTaskPage,taskStatusLabel,type CourseListItem,type TaskListItem}from'../../utils/teachingApi';defineEmits<{navigate:[payload:{key:string;name:string}]}>();const courses=ref<CourseListItem[]>([]),tasks=ref<TaskListItem[]>([]),message=ref('');const d=new Date();const today=`${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日`;const published=computed(()=>tasks.value.filter(t=>t.taskStatus===2).length),drafts=computed(()=>tasks.value.filter(t=>t.taskStatus===1).length),students=computed(()=>courses.value.reduce((n,c)=>n+c.studentCount,0));const actions=[{key:'my-task',name:'发布任务',icon:'M12 5v14M5 12h14'},{key:'my-score',name:'成绩评定',icon:'m4 12 5 5L20 6'},{key:'my-resource',name:'教学资源',icon:'M4 4h16v16H4z M8 8h8M8 12h8M8 16h5'},{key:'lab-reserve',name:'场地预约',icon:'M3 10 12 3l9 7v10H3z M9 20v-6h6v6'}];onMounted(async()=>{try{const[c,t]=await Promise.all([getCoursePage({pageNum:1,pageSize:500}),getTaskPage({pageNum:1,pageSize:500})]);courses.value=c.records;tasks.value=t.records}catch(e){message.value=e instanceof Error?e.message:'首页数据加载失败'}});
</script><style scoped>.page{height:100%;overflow:auto;padding:28px 36px;background:transparent;color:#172033}.page>header h2{margin:0}.page>header p{color:#7b8495}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:18px 0}.stats button,.quick button,.card{border:1px solid #e7ebf1;border-radius:12px;background:#fff}.stats button{padding:16px;text-align:left}.stats span{display:block;color:#7b8495}.stats strong{font-size:26px}.quick{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.quick button{display:flex;align-items:center;gap:10px;padding:14px}.quick svg{width:24px;height:24px;fill:none;stroke:#2563eb;stroke-width:2}.card{padding:18px}.card>header{display:flex;justify-content:space-between}.card h3{margin:0}.card header button{border:0;background:none;color:#2563eb}.row{display:grid;grid-template-columns:1fr auto 150px;gap:15px;align-items:center;padding:13px 0;border-bottom:1px solid #eef1f5;font-size:13px}.row small{display:block;margin-top:4px;color:#7b8495}.row>span{color:#1d4ed8}.row time{color:#7b8495}.empty{text-align:center;padding:45px;color:#8992a2}.error{color:#b42336}@media(max-width:800px){.stats,.quick{grid-template-columns:1fr 1fr}.row{grid-template-columns:1fr}}</style>
